CREATE TABLE datasets(id text PRIMARY KEY, payload jsonb NOT NULL, position bigint GENERATED BY DEFAULT AS IDENTITY);
CREATE TABLE patents(dataset_id text NOT NULL REFERENCES datasets(id), id text NOT NULL, payload jsonb NOT NULL, PRIMARY KEY(dataset_id,id));
CREATE TABLE conversations(id text PRIMARY KEY, dataset_id text NOT NULL REFERENCES datasets(id), title text NOT NULL, updated_at text NOT NULL);
CREATE TABLE runs(id text PRIMARY KEY, conversation_id text NOT NULL REFERENCES conversations(id), payload jsonb NOT NULL, position bigint GENERATED BY DEFAULT AS IDENTITY);
CREATE TABLE events(seq bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, run_id text NOT NULL REFERENCES runs(id), event text NOT NULL, payload jsonb NOT NULL);
CREATE INDEX events_run_sequence ON events(run_id,seq);
-- Saved report snapshots remain available after their source conversation is deleted.
CREATE TABLE reports(id text PRIMARY KEY,title text NOT NULL,run_id text NOT NULL,payload jsonb NOT NULL,created_at text NOT NULL);
CREATE TABLE monitors(key text PRIMARY KEY,payload jsonb NOT NULL);
CREATE TABLE sessions(token text PRIMARY KEY,expires_at bigint NOT NULL);
CREATE TABLE settings(key text PRIMARY KEY,value text NOT NULL);
CREATE TABLE results(id text PRIMARY KEY,payload jsonb NOT NULL,position bigint GENERATED BY DEFAULT AS IDENTITY);
CREATE TABLE claim_checkpoints(dataset_id text NOT NULL,patent_id text NOT NULL,method text NOT NULL,claim_number integer NOT NULL,chunk_start integer NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(dataset_id,patent_id,method,claim_number,chunk_start));
CREATE TABLE effect_checkpoints(dataset_id text NOT NULL,patent_id text NOT NULL,method text NOT NULL,section text NOT NULL,chunk_start integer NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(dataset_id,patent_id,method,section,chunk_start));
CREATE TABLE comparison_checkpoints(key text PRIMARY KEY,payload jsonb NOT NULL);
CREATE INDEX patents_dataset ON patents(dataset_id);
CREATE INDEX runs_conversation ON runs(conversation_id,position);
